     1	import type { Html, HtmlBuilder } from "foldkit/html";
     2	
     3	/** One point on a line chart. `x` runs 0..1 along the plot; `joinsPrevious` draws the segment from the point before. */
     4	export interface ChartPoint {
     5	  readonly x: number;
     6	  readonly score: number | null;
     7	  readonly joinsPrevious: boolean;
     8	}
     9	
    10	export interface LineChartOptions {
    11	  readonly points: ReadonlyArray<ChartPoint>;
    12	  readonly ariaLabel: string;
    13	  /** viewBox width; the height is fixed at 120. */
    14	  readonly width?: number;
    15	  readonly dotRadius?: number;
    16	  /** Draws the last dot in brass. */
    17	  readonly highlightLast?: boolean;
    18	  /** x positions 0..1 of faint vertical marker lines. */
    19	  readonly guides?: ReadonlyArray<number>;
    20	  readonly className?: string;
    21	}
    22	
    23	const HEIGHT = 120;
    24	const MIN_SCORE = 1;
    25	const MAX_SCORE = 5;
    26	
    27	export const CHART_PAD = { left: 24, right: 16, top: 16, bottom: 24 } as const;
    28	
    29	/** Left offset of x (0..1) as a CSS percentage of the chart width, so HTML overlays line up with the plot. */
    30	export const plotPercent = (x: number, width = 360): string => {
    31	  const chartWidth = width - CHART_PAD.left - CHART_PAD.right;
    32	  return `${((CHART_PAD.left + x * chartWidth) / width) * 100}%`;
    33	};
    34	
    35	/** Hand-built SVG line chart. A null score is a gap: the line breaks and no dot is drawn. */
    36	export const lineChart = <Message>(options: LineChartOptions, h: HtmlBuilder<Message>): Html => {
    37	  const width = options.width ?? 360;
    38	  const dotRadius = options.dotRadius ?? 4;
    39	  const chartWidth = width - CHART_PAD.left - CHART_PAD.right;
    40	  const chartHeight = HEIGHT - CHART_PAD.top - CHART_PAD.bottom;
    41	  const { points } = options;
    42	
    43	  const getX = (x: number) => CHART_PAD.left + x * chartWidth;
    44	  const getY = (score: number) => {
    45	    const norm = (score - MIN_SCORE) / (MAX_SCORE - MIN_SCORE);
    46	    return CHART_PAD.top + (1 - norm) * chartHeight;
    47	  };
    48	
    49	  const svgChildren: Array<Html> = [];
    50	
    51	  // Horizontal guide lines at 1.0, 3.0, 5.0
    52	  for (const s of [1, 3, 5]) {
    53	    const y = getY(s);
    54	    svgChildren.push(
    55	      h.line([
    56	        h.X1(String(CHART_PAD.left)),
    57	        h.Y1(String(y)),
    58	        h.X2(String(width - CHART_PAD.right)),
    59	        h.Y2(String(y)),
    60	        h.Class("stroke-line"),
    61	      ]),
    62	    );
    63	  }
    64	
    65	  // Vertical marker guides
    66	  for (const x of options.guides ?? []) {
    67	    svgChildren.push(
    68	      h.line([
    69	        h.X1(String(getX(x))),
    70	        h.Y1(String(CHART_PAD.top)),
    71	        h.X2(String(getX(x))),
    72	        h.Y2(String(HEIGHT - CHART_PAD.bottom)),
    73	        h.Class("stroke-brass"),
    74	        h.StrokeDasharray("2 3"),
    75	        h.AriaHidden(true),
    76	      ]),
    77	    );
    78	  }
    79	
    80	  // Draw lines between consecutive non-gap points
    81	  for (let i = 1; i < points.length; i++) {
    82	    const p1 = points[i - 1]!;
    83	    const p2 = points[i]!;
    84	    if (p1.score !== null && p2.score !== null && p2.joinsPrevious) {
    85	      svgChildren.push(
    86	        h.line([
    87	          h.X1(String(getX(p1.x))),
    88	          h.Y1(String(getY(p1.score))),
    89	          h.X2(String(getX(p2.x))),
    90	          h.Y2(String(getY(p2.score))),
    91	          h.Class("stroke-primary"),
    92	          h.StrokeWidth("2"),
    93	        ]),
    94	      );
    95	    }
    96	  }
    97	
    98	  // Draw dot markers
    99	  for (let i = 0; i < points.length; i++) {
   100	    const p = points[i]!;
   101	    if (p.score !== null) {
   102	      svgChildren.push(
   103	        h.circle([
   104	          h.Cx(String(getX(p.x))),
   105	          h.Cy(String(getY(p.score))),
   106	          h.R(String(dotRadius)),
   107	          h.Class(options.highlightLast === true && i === points.length - 1 ? "fill-brass" : "fill-primary"),
   108	        ]),
   109	      );
   110	    }
   111	  }
   112	
   113	  return h.svg(
   114	    [
   115	      h.ViewBox(`0 0 ${width} ${HEIGHT}`),
   116	      h.Class(options.className ?? "h-32 w-full max-w-sm overflow-hidden"),
   117	      h.Role("img"),
   118	      h.AriaLabel(options.ariaLabel),
   119	    ],
   120	    svgChildren,
   121	  );
   122	};
   123	import { type ActionMarker, type DimensionOverview, TeamOverview } from "@surveybeat/domain";
   124	import type { Html, HtmlBuilder } from "foldkit/html";
   125	import { defineTaggedUnion } from "foldkit/schema";
   126	import { formatDate, message } from "../messages/index.ts";
   127	import { Failure } from "./api.ts";
   128	import { type ChartPoint, lineChart, plotPercent } from "./charts.ts";
   129	import { dataTable, emptyState, panel, problemView, sectionTitle, subSectionTitle } from "./components.ts";
   130	import { toggleButton } from "./results.ts";
   131	import { dimensionName } from "./pulses.ts";
   132	
   133	export const LoadedOverview = defineTaggedUnion({
   134	  Loading: {},
   135	  Loaded: { overview: TeamOverview },
   136	  Failed: { failure: Failure },
   137	});
   138	export type LoadedOverview = typeof LoadedOverview.Type;
   139	
   140	/** The viewBox width of the overview charts; the marker strip is positioned against the same width. */
   141	const OVERVIEW_WIDTH = 720;
   142	
   143	const plotBox = <Message>(children: ReadonlyArray<Html>, h: HtmlBuilder<Message>): Html =>
   144	  h.div([h.Class("flex flex-col gap-2 rounded-control bg-subtle p-4")], children);
   145	
   146	const eventGlyph = <Message>(kind: ActionMarker["kind"], h: HtmlBuilder<Message>): Html =>
   147	  h.span(
   148	    [
   149	      h.AriaHidden(true),
   150	      h.Class(
   151	        kind === "committed"
   152	          ? "block size-3 shrink-0 rounded-full border-2 border-brass bg-surface"
   153	          : "block size-3 shrink-0 rounded-full bg-primary",
   154	      ),
   155	    ],
   156	    [],
   157	  );
   158	
   159	const markerText = (marker: ActionMarker): string =>
   160	  message(marker.kind === "committed" ? "overview.marker.committed" : "overview.marker.done", {
   161	    date: formatDate(new Date(marker.at)),
   162	    title: marker.title,
   163	  });
   164	
   165	const tooltipClass =
   166	  "pointer-events-none invisible absolute bottom-full left-1/2 z-10 mb-1 -translate-x-1/2 whitespace-nowrap rounded-control bg-evergreen px-2 py-1 text-xs text-on-primary group-hover:visible group-focus-visible:visible group-focus:visible";
   167	
   168	/** One Action marker: a focusable button whose title shows on hover and keyboard focus. */
   169	const markerButton = <Message>(marker: ActionMarker, x: number, h: HtmlBuilder<Message>): Html => {
   170	  const text = markerText(marker);
   171	  return h.button(
   172	    [
   173	      h.Type("button"),
   174	      h.AriaLabel(text),
   175	      h.Class("group absolute top-1 flex size-6 -translate-x-1/2 items-center justify-center rounded-full"),
   176	      h.Style({ left: plotPercent(x, OVERVIEW_WIDTH) }),
   177	    ],
   178	    [eventGlyph(marker.kind, h), h.span([h.Role("tooltip"), h.Class(tooltipClass)], [text])],
   179	  );
   180	};
   181	
   182	const legend = <Message>(h: HtmlBuilder<Message>): Html =>
   183	  h.p(
   184	    [h.Class("flex flex-wrap items-center gap-4 text-[13px] text-muted")],
   185	    [
   186	      h.span(
   187	        [h.Class("flex items-center gap-2")],
   188	        [eventGlyph("committed", h), message("overview.legend.committed")],
   189	      ),
   190	      h.span([h.Class("flex items-center gap-2")], [eventGlyph("done", h), message("overview.legend.done")]),
   191	    ],
   192	  );
   193	
   194	/** One line per Dimension; the Round x positions are shared, so each Dimension reuses them. */
   195	const dimensionPanel = <Message>(
   196	  dimension: DimensionOverview,
   197	  xByRound: ReadonlyMap<string, number>,
   198	  guides: ReadonlyArray<number>,
   199	  h: HtmlBuilder<Message>,
   200	): Html => {
   201	  const name = dimensionName(dimension.dimension);
   202	  const points: Array<ChartPoint> = [];
   203	  for (const point of dimension.points) {
   204	    const x = xByRound.get(point.roundId);
   205	    if (x !== undefined) points.push({ x, score: point.score, joinsPrevious: true });
   206	  }
   207	  return panel(
   208	    [
   209	      subSectionTitle(name, h),
   210	      plotBox(
   211	        [
   212	          lineChart(
   213	            {
   214	              points,
   215	              ariaLabel: message("overview.chartLabel", { dimension: name }),
   216	              width: OVERVIEW_WIDTH,
   217	              dotRadius: 2.5,
   218	              className: "block h-auto w-full",
   219	              guides,
   220	            },
   221	            h,
   222	          ),
   223	        ],
   224	        h,
   225	      ),
   226	    ],
   227	    h,
   228	    "flex flex-col gap-2",
   229	  );
   230	};
   231	
   232	/** Table view: one row per shared Round, one column per Dimension; a gap reads as "Too few answers". */
   233	const roundsTable = <Message>(overview: TeamOverview, h: HtmlBuilder<Message>): Html => {
   234	  const scoresByDimension = overview.dimensions.map(
   235	    (dimension) =>
   236	      new Map<string, number | null>(
   237	        dimension.points.map((point): readonly [string, number | null] => [point.roundId, point.score]),
   238	      ),
   239	  );
   240	  return dataTable(
   241	    [message("overview.tableRoundDate"), ...overview.dimensions.map((d) => dimensionName(d.dimension))],
   242	    overview.rounds.map((round) => [
   243	      round.plannedOpenDate,
   244	      ...scoresByDimension.map((scores) => {
   245	        const score = scores.get(round.roundId) ?? null;
   246	        return score !== null ? String(score) : message("overview.gap");
   247	      }),
   248	    ]),
   249	    h,
   250	  );
   251	};
   252	
   253	const markersTable = <Message>(markers: ReadonlyArray<ActionMarker>, h: HtmlBuilder<Message>): Html =>
   254	  dataTable(
   255	    [message("overview.tableDate"), message("overview.tableAction"), message("overview.tableEvent")],
   256	    markers.map((marker) => [
   257	      formatDate(new Date(marker.at)),
   258	      marker.title,
   259	      message(marker.kind === "committed" ? "overview.event.committed" : "overview.event.done"),
   260	    ]),
   261	    h,
   262	  );
   263	
   264	/** The Team health overview on the Team page: Dimension trend lines with Action markers, or tables. */
   265	export const teamOverviewView = <Message>(
   266	  state: LoadedOverview,
   267	  isTable: boolean,
   268	  onToggleTable: Message,
   269	  h: HtmlBuilder<Message>,
   270	): Html => {
   271	  if (state._tag === "Loading") {
   272	    return h.p([h.Class("text-muted")], [message("overview.loading")]);
   273	  }
   274	
   275	  if (state._tag === "Failed") {
   276	    // Organization admins outside the Team are refused; the page then simply shows no overview.
   277	    if (state.failure === "Forbidden") return null;
   278	    return problemView(state.failure, h);
   279	  }
   280	
   281	  const { overview } = state;
   282	  if (overview.rounds.length === 0) {
   283	    return h.section(
   284	      [h.Class("flex flex-col gap-4")],
   285	      [sectionTitle(message("overview.title"), h), emptyState(message("overview.empty"), h)],
   286	    );
   287	  }
   288	
   289	  // One shared time axis: planned open dates and Action times. Clamped so no point leaves the plot.
   290	  let tMin = Number.POSITIVE_INFINITY;
   291	  let tMax = Number.NEGATIVE_INFINITY;
   292	  for (const round of overview.rounds) {
   293	    tMin = Math.min(tMin, Date.parse(round.plannedOpenDate));
   294	    tMax = Math.max(tMax, Date.parse(round.plannedOpenDate));
   295	  }
   296	  for (const marker of overview.markers) {
   297	    tMin = Math.min(tMin, marker.at);
   298	    tMax = Math.max(tMax, marker.at);
   299	  }
   300	  const xOf = (t: number): number => {
   301	    if (tMax === tMin) return 0.5;
   302	    return Math.min(1, Math.max(0, (t - tMin) / (tMax - tMin)));
   303	  };
   304	
   305	  const xByRound = new Map<string, number>();
   306	  for (const round of overview.rounds) {
   307	    xByRound.set(round.roundId, xOf(Date.parse(round.plannedOpenDate)));
   308	  }
   309	  const markerXs = overview.markers.map((marker) => xOf(marker.at));
   310	
   311	  const children: Array<Html> = [
   312	    sectionTitle(message("overview.title"), h),
   313	    h.p([h.Class("text-muted")], [message("overview.intro")]),
   314	    h.div([h.Class("flex justify-end")], [toggleButton(isTable, onToggleTable, h)]),
   315	  ];
   316	
   317	  if (isTable) {
   318	    children.push(plotBox([roundsTable(overview, h)], h));
   319	    if (overview.markers.length > 0) {
   320	      children.push(plotBox([markersTable(overview.markers, h)], h));
   321	    }
   322	  } else {
   323	    if (overview.markers.length > 0) {
   324	      children.push(
   325	        panel(
   326	          [
   327	            plotBox(
   328	              [
   329	                h.div(
   330	                  [
   331	                    h.Role("group"),
   332	                    h.AriaLabel(message("overview.markersLabel")),
   333	                    h.Class("relative h-8 w-full"),
   334	                  ],
   335	                  overview.markers.map((marker, i) => markerButton(marker, markerXs[i] ?? 0.5, h)),
   336	                ),
   337	                legend(h),
   338	              ],
   339	              h,
   340	            ),
   341	          ],
   342	          h,
   343	          "flex flex-col gap-2",
   344	        ),
   345	      );
   346	    }
   347	    for (const dimension of overview.dimensions) {
   348	      children.push(dimensionPanel(dimension, xByRound, markerXs, h));
   349	    }
   350	  }
   351	
   352	  return h.section([h.Class("flex flex-col gap-4")], children);
   353	};

